package org.sleepwell.app;
import android.app.*;import android.os.Bundle;import android.widget.*;import android.view.*;import android.graphics.*;import java.util.*;import java.util.concurrent.*;
/** Original provider report, deliberately separate from a local edited interval. */
public final class HealthSleepSourceActivity extends Activity {
 final ExecutorService reader=Executors.newSingleThreadExecutor();int generation;static final String[] NAMES={"Unknown","Awake","Sleeping","Out of bed","Light","Deep","REM","Awake in bed"};
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);load();}
 void load(){LinearLayout loading=Design.page(this,false,null,n->{});RecordUi.header(loading,"Provider sleep details",this::finish);Design.text(loading,"Reading saved source…",14,400,Design.MUTED);Records.Factory factory=Records.factory;long id=getIntent().getLongExtra("record",0);int request=++generation;reader.execute(()->{try(Store store=factory.open(getApplicationContext())){RecordEntry record=Records.get(store,id);HealthSleep source=HealthSleepCodec.read(record.healthConnect);if(source==null)throw new IllegalArgumentException("This record has no Health Connect source.");runOnUiThread(()->{if(!isDestroyed()&&request==generation)show(record,source);});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Provider sleep details",this::finish);Design.text(body,e.getMessage()==null?"Source details are unavailable.":e.getMessage(),15,400,Design.MUTED);Design.button(body,"Try again",true,this::load);});}});}
 void show(RecordEntry record,HealthSleep source){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Provider sleep details",this::finish);Design.space(body,16);Design.text(body,source.origin,18,600,Design.INK);Design.space(body,6);Design.text(body,"Original provider report · local edits stay separate",13,400,Design.MUTED);Design.space(body,20);Design.text(body,RecordUi.duration(source.duration()),42,700,Design.INK);Design.text(body,"Reported period excluding awake stages",13,400,Design.MUTED);java.time.ZoneId startZone=source.startOffset==null?record.zone():java.time.ZoneOffset.ofTotalSeconds(source.startOffset),endZone=source.endOffset==null?record.zone():java.time.ZoneOffset.ofTotalSeconds(source.endOffset);PlanActivity.detail(body,"moon","Start",RecordUi.date(source.start,startZone),RecordUi.clock(this,source.start,startZone),null);PlanActivity.detail(body,"sun","End",RecordUi.date(source.end,endZone),RecordUi.clock(this,source.end,endZone),null);RecordUi.heading(body,"Source-reported stages");if(source.stages.isEmpty())Design.text(body,"No stages were supplied. Nothing is inferred here.",14,400,Design.MUTED);else{body.addView(new StageChart(this,source),new LinearLayout.LayoutParams(-1,Design.dp(this,60)));long[] totals=new long[8];for(HealthSleep.Stage stage:source.stages)totals[stage.kind]+=stage.end-stage.start;for(int n=0;n<totals.length;n++)if(totals[n]>0)PlanActivity.detail(body,"report",NAMES[n],null,RecordUi.duration(totals[n]),null);long covered=0;for(long duration:totals)covered+=duration;if(covered<source.end-source.start)PlanActivity.detail(body,"info","Unreported stage time",null,RecordUi.duration(source.end-source.start-covered),null);}if(!source.title.isEmpty()){RecordUi.heading(body,"Original title");Design.text(body,source.title,15,500,Design.INK);}if(!source.notes.isEmpty()){RecordUi.heading(body,"Original notes");Design.text(body,source.notes,14,400,Design.MUTED);}Design.space(body,16);Design.text(body,"Stage labels come from the source app, not SleepWell's phone sensors. No movement or audio was imported.",12,400,Design.MUTED);}
 static final class StageChart extends View {final HealthSleep source;final Paint paint=new Paint(3);StageChart(android.content.Context c,HealthSleep source){super(c);this.source=source;setContentDescription("Original source-reported stage intervals. Gaps are unreported.");}protected void onDraw(Canvas canvas){float top=Design.dp(getContext(),18),bottom=getHeight()-Design.dp(getContext(),18);long span=source.end-source.start;for(HealthSleep.Stage stage:source.stages){paint.setColor(stage.awake()?0xffffb22e:stage.kind==5?0xff573681:stage.kind==4?0xffa57bed:0xffcbb2f0);canvas.drawRect(getWidth()*(stage.start-source.start)/(float)span,top,getWidth()*(stage.end-source.start)/(float)span,bottom,paint);}}}
 @Override protected void onDestroy(){generation++;reader.shutdown();super.onDestroy();}@Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}void awaitReaders(long timeout)throws Exception{if(reader.isShutdown()){if(!reader.awaitTermination(timeout,TimeUnit.MILLISECONDS))throw new TimeoutException();}else reader.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);}
}
